const int TOMBOL = 2;
const int LED = 8;

void setup() {
  pinMode(TOMBOL, INPUT_PULLUP);
  pinMode(LED, OUTPUT);
}

void loop() {
  if (digitalRead(TOMBOL) == LOW) {  // tombol ditekan
    digitalWrite(LED, HIGH);
  } else {
    digitalWrite(LED, LOW);
  }
}

const int RELAY = 7;

void setup() {
  pinMode(RELAY, OUTPUT);
  digitalWrite(RELAY, HIGH);  // awal: relay mati (active LOW)
}

void loop() {
  digitalWrite(RELAY, LOW);   // relay ON
  delay(3000);
  digitalWrite(RELAY, HIGH);  // relay OFF
  delay(3000);
}
